// usage: node done7-luis-a2a.mjs '<json action>' [payloadFile.json]
// Sends one A2A data part; if a payload file is given, its JSON is merged into the action.
import fs from 'node:fs';
const D = process.env.DONE7_DIR;
const key = JSON.parse(fs.readFileSync(D + '/luis-token.json', 'utf8')).key;
let action = JSON.parse(process.argv[2]);
if (process.argv[3]) Object.assign(action, JSON.parse(fs.readFileSync(process.argv[3], 'utf8')));
const body = { jsonrpc: '2.0', id: 1, method: 'message/send', params: { message: { role: 'user', messageId: 'm' + Date.now() + Math.random().toString(36).slice(2), parts: [{ kind: 'data', data: action }] } } };
const r = await fetch('http://localhost:8810/a2a', { method: 'POST', headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
const j = await r.json();
const d = j.result?.parts?.[0]?.data ?? j;
process.stdout.write(JSON.stringify(d, null, 1));
EOF
